@pytest.mark.parametrize('index,expected', [(pd.Index(['a', 'bb', 'ccc']), "Index(['a', 'bb', 'ccc'], dtype='object')"), (pd.Index(['a', 'bb', 'ccc'] * 10), "Index(['a', 'bb', 'ccc', 'a', 'bb', 'ccc', 'a', 'bb', 'ccc', 'a', 'bb', 'ccc',\n       'a', 'bb', 'ccc', 'a', 'bb', 'ccc', 'a', 'bb', 'ccc', 'a', 'bb', 'ccc',\n       'a', 'bb', 'ccc', 'a', 'bb', 'ccc'],\n      dtype='object')"), (pd.Index(['a', 'bb', 'ccc'] * 100), "Index(['a', 'bb', 'ccc', 'a', 'bb', 'ccc', 'a', 'bb', 'ccc', 'a',\n       ...\n       'ccc', 'a', 'bb', 'ccc', 'a', 'bb', 'ccc', 'a', 'bb', 'ccc'],\n      dtype='object', length=300)"), (pd.Index(['あ', 'いい', 'ううう']), "Index(['あ', 'いい', 'ううう'], dtype='object')"), (pd.Index(['あ', 'いい', 'ううう'] * 10), "Index(['あ', 'いい', 'ううう', 'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう',\n       'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう',\n       'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう'],\n      dtype='object')"), (pd.Index(['あ', 'いい', 'ううう'] * 100), "Index(['あ', 'いい', 'ううう', 'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう', 'あ',\n       ...\n       'ううう', 'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう', 'あ', 'いい', 'ううう'],\n      dtype='object', length=300)")])
def test_string_index_repr(self, index, expected):
    result = repr(index)
    assert result == expected